render.script:
(async function() {
  function normalize(links) {
    var arr = Array.from(links);
    if (!arr.length) return;
    var parsed = arr.map(function(link, i) {
      var numEl = link.querySelector('.title-detail__row-num') || link;
      var numText = (numEl ? numEl.textContent : '').trim();
      var subEl = link.querySelector('.title-detail__row-sub, .title-detail__row-name');
      var subText = (subEl ? subEl.textContent : '').trim();
      var full = (numText + ' ' + subText).toLowerCase();
      var m = numText.match(/(\d+(?:\.\d+)?)/);
      if (!m) m = full.match(/(?:ch(?:apter)?\.?\s*|\b)(\d+(?:\.\d+)?)/);
      var num = m ? parseFloat(m[1]) : null;
      return { link: link, numEl: numEl, text: full, num: num, idx: i };
    });
    var valid = parsed.map(function(x) { return x.num; }).filter(function(n) { return n !== null && !isNaN(n); });
    var max = valid.length > 0 ? Math.max.apply(null, valid) : 0;
    parsed.forEach(function(item) {
      if (item.num !== null && !isNaN(item.num)) {
        item.link.setAttribute('data-number', String(item.num));
        if (item.numEl) item.numEl.setAttribute('data-number', String(item.num));
        return;
      }
      var t = item.text;
      var assigned = null;
      if (t.includes('start') || t.includes('prologue') || t.includes('intro') || t.includes('oneshot')) {
        assigned = 0;
      } else if (t.includes('end') || t.includes('finale') || t.includes('final') || t.includes('epilogue') || t.includes('outro')) {
        max = max + 1;
        assigned = max;
      } else {
        var prev = null;
        for (var k = item.idx - 1; k >= 0; k--) {
          if (parsed[k].num !== null && !isNaN(parsed[k].num)) { prev = parsed[k].num; break; }
        }
        var next = null;
        for (var j = item.idx + 1; j < parsed.length; j++) {
          if (parsed[j].num !== null && !isNaN(parsed[j].num)) { next = parsed[j].num; break; }
        }
        if (prev !== null && next !== null) assigned = (prev + next) / 2;
        else if (prev !== null) assigned = prev + 0.1;
        else if (next !== null) assigned = Math.max(0, next - 0.1);
        else assigned = item.idx + 1;
      }
      item.num = assigned;
      item.link.setAttribute('data-number', String(assigned));
      if (item.numEl) item.numEl.setAttribute('data-number', String(assigned));
    });
  }

  var wrap = document.getElementById('sumizuri-chapters');
  if (!wrap) {
    wrap = document.createElement('div');
    wrap.id = 'sumizuri-chapters';
    document.body.appendChild(wrap);
  }
  wrap.innerHTML = '';
  var seenHrefs = new Set();

  function harvest() {
    var list = document.querySelector('.title-detail__list');
    var links = list ? list.querySelectorAll('a.title-detail__row-link') : document.querySelectorAll('.title-detail__row a.title-detail__row-link');
    links.forEach(function(a) {
      if (a.closest('#sumizuri-chapters')) return;
      var href = a.getAttribute('href');
      if (href && !seenHrefs.has(href)) {
        seenHrefs.add(href);
        wrap.appendChild(a.cloneNode(true));
      }
    });
  }

  harvest();

  var start = Date.now();
  var nextSel = '.title-detail__chapters-pager .npager__num.is-active + .npager__num, .title-detail__chapters-pager .npager__nav[aria-label="Next page"], .npager__num.is-active + .npager__num, .npager__nav[aria-label="Next page"]';
  for (var p = 1; p < 100; p++) {
    if (Date.now() - start > 11000) break;
    var nextBtn = document.querySelector(nextSel);
    if (!nextBtn || nextBtn.disabled || nextBtn.getAttribute('aria-disabled') === 'true' || nextBtn.classList.contains('disabled')) {
      break;
    }
    var list = document.querySelector('.title-detail__list');
    var firstEl = list ? list.querySelector('a.title-detail__row-link') : null;
    var firstHref = firstEl ? firstEl.getAttribute('href') : null;

    nextBtn.click();

    await new Promise(function(resolve) {
      var count = 0;
      var iv = setInterval(function() {
        count++;
        var curList = document.querySelector('.title-detail__list');
        var curFirst = curList ? curList.querySelector('a.title-detail__row-link') : null;
        var curHref = curFirst ? curFirst.getAttribute('href') : null;
        if ((curHref && curHref !== firstHref) || count >= 20 || Date.now() - start > 11500) {
          clearInterval(iv);
          resolve();
        }
      }, 50);
    });

    harvest();
  }

  if (wrap.children.length > 0) {
    var origList = document.querySelector('.title-detail__list');
    if (origList) origList.remove();
    normalize(wrap.querySelectorAll('a.title-detail__row-link'));
  } else {
    normalize(document.querySelectorAll('.title-detail__row a.title-detail__row-link, a.title-detail__row-link'));
  }
  return 'Done';
})()

(function() {
  var el = document.querySelector('.reader, .reader__strip, .reader__paged, .reader__page');
  if (!el) return;
  var k = Object.keys(el).find(function(x) { return x.startsWith('__reactFiber$') || x.startsWith('__reactInternalInstance$'); });
  var f = k ? el[k] : null;
  var pages = null;
  var visited = new Set();
  function search(node, depth) {
    if (!node || depth > 20 || visited.has(node) || pages) return;
    visited.add(node);
    var h = node.memoizedState;
    while (h) {
      var s = h.memoizedState;
      if (s) {
        if (Array.isArray(s.pages) && s.pages.length > 0 && (s.pages[0].url || typeof s.pages[0] === 'string')) {
          pages = s.pages;
          return;
        }
        if (Array.isArray(s) && s.length > 0 && (s[0].url || typeof s[0] === 'string')) {
          pages = s;
          return;
        }
      }
      h = h.next;
    }
    var p = node.memoizedProps;
    if (p && Array.isArray(p.pages) && p.pages.length > 0 && (p.pages[0].url || typeof p.pages[0] === 'string')) {
      pages = p.pages;
      return;
    }
    if (node.return) search(node.return, depth + 1);
    if (node.child) search(node.child, depth + 1);
    if (node.sibling) search(node.sibling, depth + 1);
  }
  search(f, 0);
  var wrap = document.getElementById('sumizuri-pages');
  if (!wrap) {
    wrap = document.createElement('div');
    wrap.id = 'sumizuri-pages';
    document.body.appendChild(wrap);
  }
  wrap.innerHTML = '';
  if (pages && pages.length > 0) {
    pages.forEach(function(item) {
      var img = document.createElement('img');
      img.className = 'reader-img';
      img.src = item.url || item;
      wrap.appendChild(img);
    });
    var r = document.querySelector('.reader');
    if (r) r.remove();
  } else {
    var els = document.querySelectorAll('.reader__page, .reader-swiper__slide');
    els.forEach(function(slide) {
      var k2 = Object.keys(slide).find(function(x) { return x.startsWith('__reactFiber$') || x.startsWith('__reactInternalInstance$'); });
      var f2 = k2 ? slide[k2] : null;
      while (f2 && (!f2.memoizedProps || !(f2.memoizedProps.page || (f2.memoizedProps.children && f2.memoizedProps.children.props && f2.memoizedProps.children.props.page)))) {
        f2 = f2.return;
      }
      var p2 = f2 && f2.memoizedProps ? (f2.memoizedProps.page || (f2.memoizedProps.children && f2.memoizedProps.children.props && f2.memoizedProps.children.props.page)) : null;
      var url = p2 && p2.url ? p2.url : (Array.isArray(p2) && p2[0] && p2[0].url ? p2[0].url : null);
      if (url) {
        var img = document.createElement('img');
        img.className = 'reader-img';
        img.src = url;
        wrap.appendChild(img);
      }
    });
    if (wrap.children.length > 0) {
      var r = document.querySelector('.reader');
      if (r) r.remove();
    }
  }
})()
